runtimeModules.example:
import { use, tween, timeline } from 'motionary/runtime';
use();
tween('.box', { to: { x: 120, opacity: 1 }, duration: 500, ease: 'back-out' });
timeline().to('.a', { to: { y: -20 } }).to('.b', { to: { scale: 1.2 } }, '<+=100');

import { use } from 'motionary/runtime';
import { formatCss, parseKeyframes, playKeyframes } from 'motionary/runtime/format-css';
use(formatCss);
const [pulse] = parseKeyframes('@keyframes pulse { from { opacity: .4 } 50% { opacity: 1; transform: scale(1.1) } to { opacity: .4 } }');
playKeyframes(document.querySelector('.dot'), pulse, { duration: 1200, repeat: -1 });

import { use } from 'motionary/runtime';
import { formatMotion, playMotion } from 'motionary/runtime/format-motion';
use(formatMotion);
playMotion(document.querySelector('.card'), { initial: { opacity: 0, y: 40 }, animate: { opacity: 1, y: 0 }, transition: { type: 'spring', stiffness: 180, damping: 14 } });

import { use, timeline } from 'motionary/runtime';
import { scroll, scrollScene } from 'motionary/runtime/scroll';
use(scroll);
const tl = timeline({ paused: true }).to('.card', { to: { x: 200, rotate: 8 } });
scrollScene({ trigger: '.section', start: 'top 80%', end: 'bottom 20%', scrub: 120, pin: true, markers: true, animation: tl });

import { use } from 'motionary/runtime';
import { formatSvg, playSmil, morphPath } from 'motionary/runtime/format-svg';
use(formatSvg);
const player = playSmil(document.querySelector('svg'));
player.timeline.timeScale = 0.5;   // scrub / slow down / reverse like any runtime timeline
const f = morphPath('M0 0 L100 0 L50 80 Z', 'M50 0 A40 40 0 1 1 49.9 0 Z');
path.setAttribute('d', f(0.5));

import { use, tween } from 'motionary/runtime';
import { text, splitText } from 'motionary/runtime/text';
use(text);
const { chars } = splitText(document.querySelector('h1'), { type: 'chars,words' });
tween(chars, { from: { y: '1em', opacity: 0 }, to: { y: '0em', opacity: 1 }, stagger: 30 });

import { use } from 'motionary/runtime';
import { formatSprite, parseSpriteSheet, spritePlayer } from 'motionary/runtime/format-sprite';
use(formatSprite);
const sheet = parseSpriteSheet(await (await fetch('/slime.json')).json());
const img = new Image(); img.src = '/slime.png'; await img.decode();
spritePlayer(document.querySelector('canvas'), sheet, img, { tag: 'bounce' });

import { use } from 'motionary/runtime';
import { smooth, smoothScroll } from 'motionary/runtime/smooth';
use(smooth);
const s = smoothScroll({ lerp: 0.1, anchors: { offset: -64 } });
s.scrollTo('#pricing');

import { use } from 'motionary/runtime';
import { formatGif, loadGif, animatedImagePlayer } from 'motionary/runtime/format-gif';
use(formatGif);
const gif = await loadGif('/loader.gif');
const player = animatedImagePlayer(document.querySelector('canvas'), gif);
player.pause(); player.progress = 0.5; // scrub

import { use } from 'motionary/runtime';
import { formatApng, loadApng, animatedImagePlayer } from 'motionary/runtime/format-apng';
use(formatApng);
const anim = await loadApng('/sticker.png');
animatedImagePlayer(document.querySelector('canvas'), anim);

import { use } from 'motionary/runtime';
import { formatWebp, loadWebp, animatedImagePlayer } from 'motionary/runtime/format-webp';
use(formatWebp);
const anim = await loadWebp('/hero.webp');
const p = animatedImagePlayer(document.querySelector('canvas'), anim, { speed: 0.5 });

import { use } from 'motionary/runtime';
import { gl, createRenderer, Scene, Camera, GlNode, torus, standardMaterial } from 'motionary/runtime/gl';
use(gl);
const r = createRenderer(canvas);
const scene = new Scene();
scene.add(new GlNode('donut', { geometry: torus(), material: standardMaterial({ color: [0.5, 0.55, 1, 1] }) }));
r.resize(); r.render(scene, new Camera({ position: [0, 0.5, 3] }));

import { use } from 'motionary/runtime';
import { gl, createRenderer, Scene, Camera, frameNode } from 'motionary/runtime/gl';
import { formatGltf, loadGltf } from 'motionary/runtime/format-gltf';
use(gl, formatGltf);
const model = await loadGltf('/models/chair.glb');
const scene = new Scene().add(model), cam = new Camera();
frameNode(cam, model);
const r = createRenderer(canvas); r.resize(); r.render(scene, cam);

import { use } from 'motionary/runtime';
import { gl, Scene } from 'motionary/runtime/gl';
import { formatObj, loadObj } from 'motionary/runtime/format-obj';
use(gl, formatObj);
const cube = await loadObj('/models/cube.obj'); // + cube.mtl + textures next to it
new Scene().add(cube);

import { use } from 'motionary/runtime';
import { vector, loadLottie, lottiePlayer } from 'motionary/runtime/vector';
use(vector);
const { animation } = await loadLottie('/anim/hero.lottie');
const player = lottiePlayer(canvas, animation, { loop: true });
player.play();

// npm i @rive-app/canvas
import { defineRive } from 'motionary/components/widgets';
defineRive();
// <usa-rive src="/anim/icon.riv" state-machine="State Machine 1" autoplay></usa-rive>

import { use } from 'motionary/runtime';
import { physics, createWorld } from 'motionary/runtime/physics';
use(physics);
const world = createWorld({ gravity: [0, 980] });
world.bounds(600, 400);
const ball = world.body({ shape: 'circle', x: 300, y: 40, radius: 20, restitution: 0.7 });
world.run(); // steps on the shared ticker

import { use } from 'motionary/runtime';
import { physics } from 'motionary/runtime/physics';
import { formatScene, sceneToWorld } from 'motionary/runtime/format-scene';
use(physics, formatScene);
const { world, bodies } = sceneToWorld(await (await fetch('/scenes/stack.json')).json());
world.run();

import { use } from 'motionary/runtime';
import { dragSnap, createDragSnap } from 'motionary/runtime/drag-snap';
use(dragSnap);
const track = document.querySelector('.track');
const ds = createDragSnap(track, { axis: 'x', snap: [0, -320, -640], onUpdate: (x) => (track.style.transform = `translateX(${x}px)`) });
ds.snapTo(1);

import { use } from 'motionary/runtime';
import { gl } from 'motionary/runtime/gl';
import { formatGltf, loadGltf } from 'motionary/runtime/format-gltf';
import { gltfAnim, gltfAnimator } from 'motionary/runtime/gltf-anim';
use(gl, formatGltf, gltfAnim);
const model = await loadGltf('/models/robot.glb');
const anim = gltfAnimator(model, { clip: 'walk' });
anim.play(); // or anim.update(dt) in your own loop

import { use } from 'motionary/runtime';
import { vector, loadLottie } from 'motionary/runtime/vector';
import { lottieState, applyTheme, createStateMachine } from 'motionary/runtime/lottie-state';
use(vector, lottieState);
const { animation, dotLottie } = await loadLottie('/anim/button.lottie');
const themed = applyTheme(animation, dotLottie.themes.dark);
const sm = createStateMachine(dotLottie.stateMachines.toggle, { onState: (s) => console.log(s.name) });
sm.fire('tap');

import { use } from 'motionary/runtime';
import { gl } from 'motionary/runtime/gl';
import { formatGltf, loadGltf } from 'motionary/runtime/format-gltf';
import { gltfDecoders, provideGltfDecoder, prepareGltf } from 'motionary/runtime/gltf-decoders';
use(gl, formatGltf, gltfDecoders);
provideGltfDecoder('draco', () => import('draco3d'));
const model = await loadGltf('/models/robot-draco.glb', { prepare: prepareGltf });

